def run_tests(tests):
    passed = failed = 0
    for name, fn in tests.items():
        try:
            fn()
            passed += 1
        except AssertionError:
            failed += 1
            print("FAILED", name)
    print(f"{passed} passed, {failed} failed")


def t_add():
    assert 1 + 1 == 2


def t_len():
    assert len('abc') == 3


def t_bad():
    assert round(2.675, 2) == 2.68


run_tests({'t_add': t_add, 't_len': t_len, 't_bad': t_bad})

