guided.solution:
def valid_message(msg):
    return len(msg) <= 50 and msg[:1].isupper() and not msg.endswith('.')


for m in ['Add cleaning tests', 'add tests', 'Fix country labels.', 'A' * 60]:
    print(valid_message(m))
